import fs from "node:fs";
import path from "node:path";
import yamlModule from "./yamlModule.js";

/**
 * 拼装生成文件头部的注释块：Generated by 来源 + Options 配置列表。
 * @param {string} sourcePath 生成脚本的仓库相对路径，通常传 modulePath(import.meta)
 * @param {object} options 逐项写入 Options 的配置对象
 * @returns {string[]} 注释行数组，末行为注释结束行，调用方在其后拼接正文
 */
export const buildGeneratedFileHeader = (sourcePath, options) => {
    const lines = ["/**", ` * Generated by ${sourcePath}`, " * Options:"];
    for (const [k, v] of Object.entries(options)) {
        lines.push(` *     ${k}: ${JSON.stringify(v, null, 1).replace(/\n */g, " ")}`);
    }
    lines.push(" */");
    return lines;
};

/**
 * 写入 Gadget 产物：与磁盘既有内容一致时不写也不登记，返回 false；
 * 有变化时写入，且产物为 .js 时向所在目录的 .eslint-exemptions.yaml 登记 ignorePatterns。
 * @param {string} file 产物路径
 * @param {string} code 完整文件内容
 * @returns {Promise<boolean>} 内容是否有变化
 */
export const writeGadgetArtifact = async (file, code) => {
    if (code === await fs.promises.readFile(file, { encoding: "utf-8" }).catch(() => null)) {
        return false;
    }
    const folder = path.dirname(file);
    const filename = path.basename(file);
    await fs.promises.mkdir(folder, {
        recursive: true,
    });
    await fs.promises.writeFile(file, code);
    if (path.extname(file) === ".js") {
        const exemptionsName = path.join(folder, ".eslint-exemptions.yaml");
        const exemptions = await yamlModule.readFile(exemptionsName).catch(() => ({}));
        if (!Array.isArray(exemptions.ignorePatterns)) {
            exemptions.ignorePatterns = [];
        }
        if (!exemptions.ignorePatterns.includes(filename)) {
            exemptions.ignorePatterns.push(filename);
            await yamlModule.writeFile(exemptionsName, exemptions);
        }
    }
    return true;
};

export default { buildGeneratedFileHeader, writeGadgetArtifact };
